insert into public.shared_docs (collection,id,data) values ('trends','now',$j${"central": [{"en": "The Purple Spectrum", "heat": 3, "ko": "퍼플 스펙트럼 (가지색~라일락)", "links": ["https://www.vogue.co.kr/?p=788739", "https://www.hellomagazine.com/hfm/fashion-trends/927679/paris-fashion-week-ss27-trend-report/", "https://www.whowhatwear.com/fashion/shopping/what-to-buy-in-october-2026"], "outlets": ["Vogue Korea", "Hello!", "Who What Wear"], "why": "FW26 매장에선 가지색·버건디 퍼플이 대표 컬러로, SS27 런웨이에선 라일락·퍼플이 시즌의 스타로 동시에 꼽힘. 니트·코트부터 백까지 확산."}, {"en": "Check Tailoring", "heat": 3, "ko": "체크 테일러링", "links": ["https://www.whowhatwear.com/fashion/trends/autumn-winter-2026-trends", "https://coveteur.com/paris-fashion-week-trends-ss27"], "outlets": ["Who What Wear", "Coveteur", "Aza Fashions"], "why": "FW26의 체크 재킷·수트가 판매 중이고, SS27 런웨이(미우미우·샤넬·디올)에서도 체크 ‘교수 재킷’이 반복. 두 시즌 연속 신호."}, {"en": "Sheer Layering", "heat": 3, "ko": "시어 레이어링", "links": ["https://www.whowhatwear.com/fashion/trends/autumn-winter-2026-trends", "https://www.thezoereport.com/fashion/milan-fashion-week-trends-spring-2027"], "outlets": ["Who What Wear", "Coveteur", "The Zoe Report"], "why": "FW26 ‘시어’ 트렌드가 SS27 파리·밀라노·뉴욕에서 더 강해짐. 겹쳐 입는 방식으로 상업화 여지가 큼."}, {"en": "The Skirt Moment", "heat": 3, "ko": "스커트의 귀환", "links": ["https://www.whowhatwear.com/fashion/runway/milan-fashion-week-trends-spring-summer-2027", "https://gulfnews.com/the-kurator/the-best-looks-and-trends-from-milan-fashion-week-ss27-1.500692245"], "outlets": ["Who What Wear", "Gulf News", "The Zoe Report"], "why": "프라다 전 룩 스커트를 필두로 밀라노가 ‘스커트의 시즌’을 선언. 이번 달 쇼핑 리스트에도 비대칭 미디 스커트가 등장."}, {"en": "Lingerie as Outerwear", "heat": 3, "ko": "란제리 레이어링", "links": ["https://www.thezoereport.com/fashion/milan-fashion-week-trends-spring-2027", "https://www.russh.com/new-york-fashion-week-spring-summer-2027-highlights/"], "outlets": ["The Zoe Report", "RUSSH", "Aza Fashions"], "why": "카이트·프라다·발렌시아가에서 노출 브라·슬립을 겉옷처럼. 국내에선 캐미솔·슬립 레이어로 순화된 상품화가 현실적."}, {"en": "80s Shoulders & Shawl Wraps", "heat": 2, "ko": "80년대 어깨·숄 머플러", "links": ["https://www.vogue.co.kr/?p=788739"], "outlets": ["Vogue Korea", "Who What Wear"], "why": "FW26은 잘록한 허리와 과감한 어깨, 머플러로 어깨를 감싸 브로치로 고정하는 스타일링이 확산(랄프 로렌 발)."}], "month": "2026-10", "nextMonth": [{"en": "Satin Evening Separates", "ko": "새틴 이브닝 세퍼레이트", "why": "[예측] 10월 쇼핑 리스트의 새틴 시가렛 팬츠·클러치가 연말 시즌을 타고 확대될 가능성."}, {"en": "Brocade & Jacquard Jackets", "ko": "브로케이드·자카드 재킷", "why": "[예측] 이번 달 주목 아이템인 브로케이드 재킷이 홀리데이 수요와 맞물려 강해질 것."}, {"en": "Deeper Wine-Purple", "ko": "와인빛으로 짙어지는 퍼플", "why": "[예측] 가지색 퍼플이 연말 무드에 맞춰 와인·버건디 쪽으로 이동."}, {"en": "Pre-Fall Lookbooks", "ko": "프리폴 룩북 공개", "why": "[일정] 12월 전후 프리폴 2027 룩북이 공개되며 FW27의 첫 신호가 나옴."}], "nextYear": [{"en": "Skirt-led Wardrobes", "ko": "스커트 중심 워드로브", "why": "[예측] SS27의 스커트 신호가 2027 상반기 리테일에서 무릎~미디 길이 중심으로 상품화."}, {"en": "Commercial Slip Layering", "ko": "슬립·캐미솔 레이어링의 대중화", "why": "[예측] 런웨이의 란제리 노출이 니트·셔츠 위아래 레이어링으로 순화되어 확산."}, {"en": "Softened Heritage Tailoring", "ko": "부드러워진 헤리티지 테일러링", "why": "[예측] 디올의 가벼운 바 재킷, 체크 교수 재킷처럼 구조를 덜어낸 재킷이 핵심 아우터로."}, {"en": "Orange & Lilac Accents", "ko": "오렌지·라일락 포인트", "why": "[예측] 파리가 꼽은 오렌지, 시즌 스타 라일락이 2027 봄·여름 포인트 컬러로."}], "seasons": [{"items": [{"en": "Weighty Checks & Tweed Suiting", "ko": "무게감 있는 체크·트위드 수트", "why": "[예측] 두 시즌 연속 체크 신호가 FW에선 울·트위드로 무거워질 것."}, {"en": "Wine to Aubergine", "ko": "와인~오베르진 컬러", "why": "[예측] 퍼플 계열이 더 깊고 어두운 톤으로 이어짐."}, {"en": "Softened 80s Shoulder", "ko": "부드러워진 80년대 어깨", "why": "[예측] 과감한 어깨가 라운드 숄더·드레이프로 완화."}, {"en": "Maximal Accessories", "ko": "맥시멀 액세서리", "why": "[예측] SS27의 큰 벨트·장식 슈즈·프린지 백 흐름이 FW로 확장."}], "ko": "2027 가을·겨울", "label": "FW27"}, {"items": [{"en": "Edit after Excess", "ko": "맥시멀 이후의 정리", "why": "[예측] 두 시즌 이어진 맥시멀 흐름 뒤로 소재 중심의 절제가 돌아올 가능성."}, {"en": "Bias & Fluid Drape", "ko": "바이어스·유려한 드레이프", "why": "[예측] 슬립·란제리 흐름이 바이어스 컷 드레스로 진화."}, {"en": "Washed Pastels", "ko": "워시드 파스텔", "why": "[예측] 라일락의 뒤를 잇는 빛바랜 파스텔."}, {"en": "Couture Technique on Basics", "ko": "베이직 위 쿠튀르 기법", "why": "[예측] 발렌시아가식 ‘일상 쿠튀르’가 컨템포러리 브랜드까지 내려옴."}], "ko": "2028 봄·여름", "label": "SS28"}], "updatedAt": 1791874753473}$j$::jsonb) on conflict (collection,id) do nothing;
insert into public.shared_docs (collection,id,data) values ('feed','brock-new-label-paris',$j${"channel": "", "fetchedAt": 1791875843365, "heat": 1, "kind": "news", "publishedAt": "", "source": "The Zoe Report", "summary": "브록 컬렉션 공동 창립자가 5년 공백 끝에 파리에서 80피스 규모의 SS27 데뷔 컬렉션을 공개했다. 리조트 라인도 이어질 예정이다.", "tags": ["new label", "designer"], "title": "크리스 브록, 새 레이블 BROCK으로 복귀", "title_en": "Kris Brock returns with BROCK", "url": "https://www.thezoereport.com/fashion/october-2026-fashion-news"}$j$::jsonb) on conflict (collection,id) do nothing;
insert into public.shared_docs (collection,id,data) values ('feed','chanel-ss27-blazy-grand-palais',$j${"channel": "", "fetchedAt": 1791875843357, "heat": 5, "kind": "runway", "publishedAt": "2026-10-05", "source": "theFashionSpot", "summary": "황금빛 새 장식 아래 열린 쇼에서 테일코트, 시어 패널 트위드 재킷, 붉은 시퀸 코트가 등장했다. 포럼 반응은 정체성이 약하다는 비판이 다수였다.", "tags": ["sheer", "tailoring", "sequins", "tweed"], "title": "샤넬 SS27, 블라지 1주년 그랑 팔레 쇼", "title_en": "Chanel SS27: Blazy's first anniversary", "url": "https://www.thefashionspot.com/runway-news/975684-forum-members-review-the-chanel-spring-2027-collection-from-matthieu-blazy-one-year-after-becoming-creative-director"}$j$::jsonb) on conflict (collection,id) do nothing;
insert into public.shared_docs (collection,id,data) values ('feed','chanel-ss27-impression-review',$j${"channel": "", "fetchedAt": 1791875843358, "heat": 5, "kind": "runway", "publishedAt": "", "source": "The Impression", "summary": "남성 예복을 날것의 단으로 잘라 질레·팬츠·펜슬 스커트 수트로 바꾸고, 신축성 있는 스모킹 트위드와 투명도가 다른 실크 레이어를 선보였다.", "tags": ["tailoring", "tweed", "sheer"], "title": "샤넬 SS27, 남성 정장을 해체한 테일러링", "title_en": "Chanel SS27 reworks menswear tailoring", "url": "https://theimpression.com/chanel-spring-2027-fashion-show-review/"}$j$::jsonb) on conflict (collection,id) do nothing;
insert into public.shared_docs (collection,id,data) values ('feed','fendi-ss27-chiuri',$j${"channel": "Who What Wear", "fetchedAt": 1791875843362, "heat": 5, "kind": "runway", "publishedAt": "2026-09-28", "source": "Who What Wear", "summary": "마리아 그라치아 치우리의 펜디는 파스텔 퍼 트리밍, 레이스 브라를 겉옷처럼 드러낸 룩, 회색빛 데님과 새 바게트 백을 선보였다.", "tags": ["lingerie", "pastel", "denim", "fur"], "title": "펜디 SS27, 파스텔 퍼와 드러낸 브라", "title_en": "Fendi SS27: pastel fur, visible bras", "url": "https://www.whowhatwear.com/fashion/runway/fendi-spring-summer-2027"}$j$::jsonb) on conflict (collection,id) do nothing;
insert into public.shared_docs (collection,id,data) values ('feed','fw26-80s',$j${"channel": "", "fetchedAt": 1791874333473, "heat": 3, "kind": "news", "publishedAt": "", "source": "Vogue Korea", "summary": "잘록한 허리와 과감한 어깨, 가지색 퍼플, 머플러로 어깨를 감싸는 스타일링이 확산.", "tags": ["80s", "purple", "shoulder"], "title": "FW26: 80년대 어깨와 가지색 퍼플", "title_en": "FW26: 80s shoulders and aubergine", "url": "https://www.vogue.co.kr/?p=788739"}$j$::jsonb) on conflict (collection,id) do nothing;
